import React, { useEffect, useRef } from 'react';
import { Terminal } from 'xterm';
import { FitAddon } from 'xterm-addon-fit';
import 'xterm/css/xterm.css';

function TerminalComponent({ containerId }) {
  const terminalRef = useRef(null);
  const socketRef = useRef(null);
  const fitAddon = new FitAddon();

  useEffect(() => {
    // Initialize xterm.js terminal
    const terminal = new Terminal();
    terminal.loadAddon(fitAddon);
    terminal.open(terminalRef.current);
    fitAddon.fit();

    // Establish WebSocket connection to backend
    const socket = new WebSocket('ws://localhost:3001');
    socketRef.current = socket;

    socket.onopen = () => {
      socket.send(JSON.stringify({ containerId, cmd: '/bin/sh' }));
    };

    // Handle messages from backend and display in terminal
    socket.onmessage = (event) => {
      const message = JSON.parse(event.data);
      if (message.output) {
        terminal.write(message.output);
      } else if (message.error) {
        terminal.write(`\x1B[31m${message.error}\x1B[0m`); // Display errors in red
      } else if (message.message) {
        terminal.write(message.message);
      }
    };

    // Send terminal input to WebSocket
    terminal.onData((input) => {
      socket.send(JSON.stringify({ containerId, cmd: input }));
    });

    // Cleanup on component unmount
    return () => {
      socket.close();
      terminal.dispose();
    };
  }, [containerId]);

  return <div ref={terminalRef} style={{ width: '100%', height: '100%' }} />;
}

export default TerminalComponent;
